/**
 * Pull request module API client (REQ-6-1/6-2-1..4/6-3-1/6-3-2).
 *
 * Same-origin relative requests through the shared `api` client, so every failure
 * arrives as the uniform `ApiError` payload (docs/architecture.md §3) and forms
 * render field errors next to the matching control. The Commits / Files changed
 * views reuse the M4a `GET .../compare` payload (branch-name handles, §7.2) —
 * this module never re-implements diff arithmetic.
 */
import { api } from '../../api/client';
import type { DiffPayload, ViewerPermission } from '../repo/api';

export type PullState = 'draft' | 'open' | 'closed' | 'merged';

/** Repository role ladder (docs/architecture.md §4) — mirrors the backend order. */
const ROLE_ORDER = ['read', 'triage', 'write', 'maintain', 'admin'];

export function roleAtLeast(role: string | null | undefined, required: string): boolean {
  if (!role) return false;
  return ROLE_ORDER.indexOf(role) >= ROLE_ORDER.indexOf(required);
}

/** PR creation / comparison need Write or above. */
export function canWritePulls(role: string | null | undefined): boolean {
  return roleAtLeast(role, 'write');
}

/** Checks status updates need Admin (REQ-6-1). */
export function isPullAdmin(role: string | null | undefined): boolean {
  return roleAtLeast(role, 'admin');
}

/**
 * Ready for review is Author ∪ Maintain ∪ Admin (REQ-6-2-4); an organisation
 * Owner is an Admin of the organisation's repositories.
 */
export function canSetPullReady(role: string | null | undefined, isAuthor: boolean): boolean {
  return isAuthor || role === 'maintain' || roleAtLeast(role, 'admin');
}

export interface PullSummary {
  id: number;
  number: number;
  title: string;
  body: string;
  state: PullState;
  author: string | null;
  createdAt: string;
  updatedAt: string;
  baseBranch: string | null;
  compareBranch: string | null;
  baseCommitId: number | null;
  compareCommitId: number | null;
  currentCompareCommitId: number | null;
  currentCompareShortId: string | null;
  url: string;
}

export interface CheckState {
  name: string;
  status: 'pending' | 'success' | 'failure';
  setter: string | null;
  updatedAt: string | null;
  compareCommitId: number | null;
}

export interface PullComment {
  id: number;
  body: string;
  author: string | null;
  createdAt: string;
}

export interface PullActivity {
  id: number;
  kind: string;
  actor: string | null;
  payload: Record<string, unknown>;
  createdAt: string;
}

export interface PullReview {
  id: number;
  reviewer: string | null;
  decision: 'comment' | 'approve' | 'request_changes';
  summary: string;
  compareCommitId: number | null;
  createdAt: string;
}

export interface PullDetail extends PullSummary {
  checks: CheckState;
  comments: PullComment[];
  activities: PullActivity[];
  reviews: PullReview[];
  viewerPermission: ViewerPermission;
}

export interface PullCounts {
  all: number;
  draft: number;
  open: number;
  closed: number;
  merged: number;
}

export interface PullListResult {
  pulls: PullSummary[];
  counts: PullCounts;
  viewerPermission: ViewerPermission;
}

export interface BranchOption {
  name: string;
  isDefault: boolean;
}

/** Comparison payload of the PR creation flow (REQ-6-2-2). */
export interface PullComparison extends DiffPayload {
  baseBranch: string | null;
  compareBranch: string | null;
  sameBranch: boolean;
  existingPull: PullSummary | null;
}

export interface ComparisonResult {
  branches: BranchOption[];
  comparison: PullComparison | null;
  viewerPermission: ViewerPermission;
}

export interface BranchRule {
  id: number;
  branchName: string;
  requireApproval: boolean;
  requireCheckTest: boolean;
}

export interface BranchRulesResult {
  rules: BranchRule[];
  branches: BranchOption[];
  viewerPermission: ViewerPermission;
}

export interface PullListQuery {
  state?: PullState | null;
  author?: string;
  review?: string | null;
}

const encode = (value: string | number) => encodeURIComponent(String(value));
const base = (owner: string, name: string) => `/api/repos/${encode(owner)}/${encode(name)}`;
const pullBase = (owner: string, name: string, number: number) => `${base(owner, name)}/pulls/${encode(number)}`;

export const pullApi = {
  list: (owner: string, name: string, query: PullListQuery = {}) => {
    const params = new URLSearchParams();
    if (query.state) params.set('state', query.state);
    if (query.author) params.set('author', query.author);
    if (query.review) params.set('review', query.review);
    const search = params.toString();
    return api.get<PullListResult>(`${base(owner, name)}/pulls${search ? `?${search}` : ''}`);
  },

  detail: (owner: string, name: string, number: number) =>
    api.get<PullDetail>(pullBase(owner, name, number)),

  compare: (owner: string, name: string, query: { base?: string; compare?: string } = {}) => {
    const params = new URLSearchParams();
    if (query.base) params.set('base', query.base);
    if (query.compare) params.set('compare', query.compare);
    const search = params.toString();
    return api.get<ComparisonResult>(`${base(owner, name)}/pulls/compare${search ? `?${search}` : ''}`);
  },

  create: (
    owner: string,
    name: string,
    input: { title: string; body: string; base: string; compare: string; draft: boolean },
  ) => api.post<{ pull: PullSummary }>(`${base(owner, name)}/pulls`, input).then((result) => result.pull),

  readyForReview: (owner: string, name: string, number: number) =>
    api.post<{ pull: PullSummary }>(`${pullBase(owner, name, number)}/ready`).then((result) => result.pull),

  checks: (owner: string, name: string, number: number) =>
    api.get<{ check: CheckState }>(`${pullBase(owner, name, number)}/checks`).then((result) => result.check),

  setCheck: (owner: string, name: string, number: number, status: string) =>
    api
      .put<{ check: CheckState }>(`${pullBase(owner, name, number)}/checks/test`, { status })
      .then((result) => result.check),

  rules: (owner: string, name: string) => api.get<BranchRulesResult>(`${base(owner, name)}/rules/branches`),

  saveRule: (
    owner: string,
    name: string,
    input: { branchName: string; requireApproval: boolean; requireCheckTest: boolean },
  ) => api.put<{ rule: BranchRule }>(`${base(owner, name)}/rules/branches`, input).then((result) => result.rule),
};

/** Route helpers, kept together so links cannot drift apart. */
export const pullPaths = {
  list: (owner: string, name: string) => `/${owner}/${name}/pulls`,
  compare: (owner: string, name: string, base?: string, compare?: string) => {
    const params = new URLSearchParams();
    if (base) params.set('base', base);
    if (compare) params.set('compare', compare);
    const search = params.toString();
    return `/${owner}/${name}/pulls/compare${search ? `?${search}` : ''}`;
  },
  detail: (owner: string, name: string, number: number, tab?: string) =>
    `/${owner}/${name}/pulls/${number}${tab ? `?tab=${tab}` : ''}`,
  branches: (owner: string, name: string) => `/${owner}/${name}/settings/branches`,
};

/** Human-readable timestamp for timelines and check metadata. */
export function formatPullTimestamp(value: string | null | undefined): string {
  if (!value) return '';
  const iso = value.includes('T') ? value : `${value.replace(' ', 'T')}Z`;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
}

/** Title of a PR state as visible text (Open / Draft / Closed / Merged). */
export const PULL_STATE_LABELS: Record<PullState, string> = {
  draft: 'Draft',
  open: 'Open',
  closed: 'Closed',
  merged: 'Merged',
};

import { useEffect, useState } from 'react';
import { Button } from '../../components/Button';
import { pullCopy } from '../../contracts/copy';
import { ApiError } from '../../api/client';
import { formatPullTimestamp, pullApi } from './api';
import type { CheckState } from './api';

/**
 * Checks area of the PR detail page (REQ-6-1).
 *
 * The status is stored per `(current compare commit, 'test')` (§9.5): the payload
 * arrives with the detail page, so the area is usable on arrival and shows
 * `test: pending` until an Admin saves a status. Only an Admin sees the
 * `test status` combobox and its `Save` button.
 */
export function PullChecks({
  owner,
  name,
  number,
  check,
  canAdmin,
  onChanged,
  headingLevel = 'h2',
}: {
  owner: string;
  name: string;
  number: number;
  check: CheckState;
  canAdmin: boolean;
  onChanged: (check: CheckState) => void;
  headingLevel?: 'h2' | 'h3';
}) {
  const Heading = headingLevel;
  const [status, setStatus] = useState(check.status);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => setStatus(check.status), [check.status]);

  const save = async (event: React.FormEvent) => {
    event.preventDefault();
    setBusy(true);
    setError(null);
    try {
      onChanged(await pullApi.setCheck(owner, name, number, status));
    } catch (thrown) {
      setError(thrown instanceof ApiError ? thrown.message : 'Something went wrong');
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className="mt-4" aria-labelledby="pr-checks-heading">
      <Heading className="section-title" id="pr-checks-heading">
        {pullCopy.checks}
      </Heading>
      <div className="app-card p-3 text-sm">
        <p className="m-0" data-check-status={check.status}>
          <span data-check-summary>
            {check.name}: {check.status}
          </span>
          {check.setter ? (
            <>
              {' · '}
              <span data-check-setter>{check.setter}</span>
            </>
          ) : null}
          {check.updatedAt ? (
            <>
              {' · '}
              <time dateTime={check.updatedAt}>{formatPullTimestamp(check.updatedAt)}</time>
            </>
          ) : null}
        </p>

        {canAdmin ? (
          <form className="mt-3 flex flex-wrap items-end gap-2" onSubmit={save}>
            <label className="form-label m-0 flex flex-col gap-1">
              {pullCopy.testStatus}
              <select
                aria-label={pullCopy.testStatus}
                className="form-input w-40"
                value={status}
                onChange={(event) => setStatus(event.target.value as CheckState['status'])}
              >
                <option value="pending">pending</option>
                <option value="success">{pullCopy.success}</option>
                <option value="failure">failure</option>
              </select>
            </label>
            <Button type="submit" variant="primary" disabled={busy}>
              {pullCopy.save}
            </Button>
          </form>
        ) : null}
        {error ? (
          <p className="form-error" role="alert">
            {error}
          </p>
        ) : null}
      </div>
    </section>
  );
}

export default PullChecks;

