import { useEffect, useState } from 'react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { Button } from '../../components/Button';
import { SegmentedNav } from '../../components/SegmentedNav';
import { useAuth } from '../../auth/AuthContext';
import {
  content as contentCopy,
  errors as errorCopy,
  moduleCopy,
  pulls as pullCopy,
} from '../../contracts/copy';
import { DiffView } from '../repo/DiffView';
import { RepoHeader, RepoNav } from '../repo/RepoHeader';
import { RepositoryMissing } from '../repo/RepositoryMissing';
import { repoApi } from '../repo/api';
import type { DiffPayload } from '../repo/api';
import { useRepository } from '../repo/useRepository';
import { PullChecks } from './PullChecks';
import {
  canSetPullReady,
  formatPullTimestamp,
  isPullAdmin,
  PULL_STATE_LABELS,
  pullApi,
  pullPaths,
} from './api';
import type { CheckState, PullDetail } from './api';

const TABS = ['conversation', 'commits', 'files_changed', 'checks'] as const;
type Tab = (typeof TABS)[number];

const ACTIVITY_LABELS: Record<string, string> = {
  pull_request_opened: pullCopy.openedActivity,
  pull_request_ready_for_review: pullCopy.readyForReviewActivity,
  pull_request_closed: pullCopy.closedActivity,
  pull_request_reopened: pullCopy.reopenedActivity,
  pull_request_merged: pullCopy.mergedActivity,
};

const REVIEW_LABELS: Record<string, string> = {
  approve: pullCopy.approved,
  request_changes: pullCopy.changesRequested,
  comment: pullCopy.conversation,
};

/**
 * PR detail page (REQ-6-1 checks area, REQ-6-2-4 draft lifecycle, REQ-6-3-1/6-3-2
 * Conversation / Commits / Files changed / Checks).
 *
 * All four views read the same persisted PR number; Conversation, Commits, Files
 * changed and Checks are navigation links (`?tab=`). The Checks area is rendered
 * on arrival (Conversation) and on its own tab, so an Admin can set the `test`
 * status without a prior action. Commits / Files changed reuse the read-only M4a
 * `/compare` endpoint with the PR's branch handles, so visitors can read a public
 * Open PR. A Draft shows the `Draft` marker, a disabled `Merge pull request`
 * button and — for the author, Maintain, Admin or organisation Owner — the
 * `Ready for review` action.
 */
export function PullDetailPage() {
  const params = useParams();
  const owner = params.owner ?? '';
  const name = params.repo ?? '';
  const number = Number.parseInt(params.number ?? '', 10);
  const repositoryState = useRepository(owner, name);
  const { user } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const rawTab = searchParams.get('tab') ?? 'conversation';
  const tab: Tab = (TABS as readonly string[]).includes(rawTab) ? (rawTab as Tab) : 'conversation';

  const [detail, setDetail] = useState<PullDetail | null>(null);
  const [missing, setMissing] = useState(false);
  const [diff, setDiff] = useState<DiffPayload | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (repositoryState.status !== 'ready' || !Number.isFinite(number)) return undefined;
    let active = true;
    pullApi
      .detail(owner, name, number)
      .then((value) => {
        if (!active) return;
        setDetail(value);
        setMissing(false);
      })
      .catch(() => {
        if (active) setMissing(true);
      });
    return () => {
      active = false;
    };
  }, [owner, name, number, repositoryState.status, user?.id]);

  // Commits / Files changed come from the viewer-readable M4a compare endpoint
  // with the PR's branch handles (docs/architecture.md §7.2, Issue #9 #235 §3).
  useEffect(() => {
    if (!detail || (tab !== 'commits' && tab !== 'files_changed')) return undefined;
    if (!detail.baseBranch || !detail.compareBranch) return undefined;
    let active = true;
    repoApi
      .compare(owner, name, { base: detail.baseBranch, compare: detail.compareBranch })
      .then((payload) => {
        if (active) setDiff(payload);
      })
      .catch(() => {
        if (active) setDiff(null);
      });
    return () => {
      active = false;
    };
  }, [tab, detail, owner, name]);

  if (repositoryState.status === 'loading') {
    return (
      <div className="page-shell">
        <p className="text-muted">Loading…</p>
      </div>
    );
  }
  if (repositoryState.status === 'missing') return <RepositoryMissing owner={owner} name={name} />;
  if (missing) {
    return (
      <div className="page-shell">
        <RepoHeader repository={repositoryState.repository} />
        <h1 className="page-title mt-4">{pullCopy.pullNotFound}</h1>
        <Link className="text-accent" to={pullPaths.list(owner, name)}>
          {pullCopy.newPullRequest}
        </Link>
      </div>
    );
  }
  if (!detail) {
    return (
      <div className="page-shell">
        <p className="text-muted">Loading…</p>
      </div>
    );
  }

  const repository = repositoryState.repository;
  const role = detail.viewerPermission.repository;
  const isAuthor = Boolean(user?.username) && user?.username === detail.author;
  const canReady = detail.state === 'draft' && canSetPullReady(role, isAuthor);

  const setTab = (next: Tab) => {
    const params2 = new URLSearchParams(searchParams);
    if (next === 'conversation') params2.delete('tab');
    else params2.set('tab', next);
    setSearchParams(params2);
  };

  const ready = async () => {
    setBusy(true);
    setActionError(null);
    try {
      await pullApi.readyForReview(owner, name, detail.number);
      setDetail(await pullApi.detail(owner, name, detail.number));
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown.message : errorCopy.unknown);
    } finally {
      setBusy(false);
    }
  };

  const onCheckChanged = (check: CheckState) => setDetail((current) => (current ? { ...current, checks: check } : current));

  const timeline = [
    ...detail.activities.map((activity) => ({
      key: `activity-${activity.id}`,
      createdAt: activity.createdAt,
      id: activity.id,
      kind: 'activity' as const,
      actor: activity.actor,
      label: ACTIVITY_LABELS[activity.kind] ?? activity.kind,
      body: null as string | null,
    })),
    ...detail.comments.map((comment) => ({
      key: `comment-${comment.id}`,
      createdAt: comment.createdAt,
      id: comment.id,
      kind: 'comment' as const,
      actor: comment.author,
      label: null as string | null,
      body: comment.body,
    })),
    ...detail.reviews.map((review) => ({
      key: `review-${review.id}`,
      createdAt: review.createdAt,
      id: review.id,
      kind: 'review' as const,
      actor: review.reviewer,
      label: REVIEW_LABELS[review.decision] ?? review.decision,
      body: review.summary || null,
    })),
  ].sort((a, b) => (a.createdAt === b.createdAt ? a.id - b.id : a.createdAt < b.createdAt ? -1 : 1));

  return (
    <div className="page-shell">
      <RepoHeader repository={repository} />
      <RepoNav
        owner={repository.owner}
        name={repository.name}
        active="pullRequests"
        showSettings={repository.viewerPermission.repository !== null}
      />

      <div className="mt-4">
        <h1 className="page-title">{detail.title}</h1>
        <p className="m-0 mt-1 text-sm text-muted">
          #{detail.number} · {detail.author}
        </p>
        <p className="m-0 mt-1 text-sm text-muted">
          <span data-branch-role="base">{detail.baseBranch}</span>
          <span aria-hidden="true"> ← </span>
          <span data-branch-role="compare">{detail.compareBranch}</span>
        </p>
        <p className="mt-2 flex flex-wrap items-center gap-2">
          <span className="badge" data-pr-state={detail.state}>
            {PULL_STATE_LABELS[detail.state]}
          </span>
          {detail.state === 'draft' ? (
            <>
              <Button disabled>{moduleCopy.mergePullRequest}</Button>
              {canReady ? (
                <Button variant="primary" disabled={busy} onClick={ready}>
                  {pullCopy.readyForReview}
                </Button>
              ) : null}
            </>
          ) : null}
        </p>
        {actionError ? (
          <p className="form-error" role="alert">
            {actionError}
          </p>
        ) : null}
      </div>

      <div className="mt-3" role="tablist">
        <SegmentedNav
          items={[
            { label: pullCopy.conversation, to: pullPaths.detail(owner, name, detail.number), active: tab === 'conversation' },
            {
              label: contentCopy.commits,
              to: pullPaths.detail(owner, name, detail.number, 'commits'),
              active: tab === 'commits',
            },
            {
              label: contentCopy.changedFiles,
              to: pullPaths.detail(owner, name, detail.number, 'files_changed'),
              active: tab === 'files_changed',
            },
            {
              label: pullCopy.checks,
              to: pullPaths.detail(owner, name, detail.number, 'checks'),
              active: tab === 'checks',
            },
          ]}
        />
      </div>

      {tab === 'conversation' ? (
        <>
          <section className="mt-4">
            <h2 className="section-title">{pullCopy.description}</h2>
            <div className="app-card p-3 text-sm">
              {detail.body ? <p className="m-0 whitespace-pre-wrap">{detail.body}</p> : <p className="m-0 text-muted">{pullCopy.noDescription}</p>}
            </div>
          </section>

          <section className="mt-4">
            <h2 className="section-title">{pullCopy.conversation}</h2>
            <ul className="app-card m-0 list-none divide-y divide-solid divide-border p-0">
              {timeline.map((entry) => (
                <li key={entry.key} className="px-3 py-2 text-sm" data-timeline-kind={entry.kind}>
                  <p className="m-0">
                    <span className="font-600">{entry.actor}</span>{' '}
                    {entry.label ? (
                      <span data-activity-kind={entry.kind === 'activity' ? ACTIVITY_LABELS_KEY(entry.label) : undefined}>
                        {entry.label}
                      </span>
                    ) : null}{' '}
                    <time className="text-muted" dateTime={entry.createdAt}>
                      {formatPullTimestamp(entry.createdAt)}
                    </time>
                  </p>
                  {entry.body ? <p className="m-0 mt-1 whitespace-pre-wrap">{entry.body}</p> : null}
                </li>
              ))}
            </ul>
          </section>

          <PullChecks
            owner={owner}
            name={name}
            number={detail.number}
            check={detail.checks}
            canAdmin={isPullAdmin(role)}
            onChanged={onCheckChanged}
          />
        </>
      ) : null}

      {tab === 'commits' ? (
        <section className="mt-4">
          <h2 className="section-title mt-0">
            {contentCopy.commits}{' '}
            <span className="badge" aria-hidden="true">
              {diff?.commits.length ?? 0}
            </span>
          </h2>
          {diff && diff.commits.length ? (
            <ul className="app-card m-0 list-none divide-y divide-solid divide-border p-0">
              {diff.commits.map((commit) => (
                <li key={commit.id} className="flex flex-wrap items-center gap-2 px-3 py-2 text-sm">
                  <Link className="text-accent font-600" to={commit.url}>
                    {commit.shortId}
                  </Link>
                  <span>{commit.message}</span>
                  <span className="text-muted">{commit.author}</span>
                  <time className="text-muted" dateTime={commit.createdAt}>
                    {formatPullTimestamp(commit.createdAt)}
                  </time>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-muted">No commits</p>
          )}
        </section>
      ) : null}

      {tab === 'files_changed' ? (
        <section className="mt-4">
          {diff ? <DiffView payload={diff} /> : <p className="text-muted">Loading…</p>}
        </section>
      ) : null}

      {tab === 'checks' ? (
        <PullChecks
          owner={owner}
          name={name}
          number={detail.number}
          check={detail.checks}
          canAdmin={isPullAdmin(role)}
          onChanged={onCheckChanged}
        />
      ) : null}

      <div className="mt-4">
        <Link className="text-accent text-sm" to={pullPaths.list(owner, name)}>
          {pullCopy.all}
        </Link>
      </div>
    </div>
  );
}

/**
 * The activity kind is not exposed on the timeline entry, so the `data-activity-kind`
 * hook is derived from the visible label. Kept next to the map so the two cannot
 * drift: an unknown label simply yields no attribute.
 */
function ACTIVITY_LABELS_KEY(label: string): string | undefined {
  return Object.entries(ACTIVITY_LABELS).find(([, value]) => value === label)?.[0];
}

export default PullDetailPage;

/**
 * M6a pull request acceptance suite (REQ-6-1 / 6-2-1 / 6-2-2 / 6-2-3 / 6-2-4 /
 * 6-3-1 / 6-3-2).
 *
 * Every test starts from a fresh browser context (the requirements' "fresh
 * unauthenticated browser session") against the real seed data (docs/seed-data.md):
 * acme-docs with the Open PR `Improve onboarding` (pr-onboarding → main,
 * `src/search.ts` + `docs/onboarding.md`, 3 additions / 1 deletion), `Fix search`,
 * a Closed PR, the Draft `Draft onboarding update` and the free comparison pair
 * (main, feature-search); alice-dev/protection-lab with an Open PR targeting
 * `main` and no protection rule. Assertions use roles and the exact accessible
 * names of the copy contract.
 *
 * Test order matters inside this file: REQ-6-2-2 only reads the
 * (main, feature-search) comparison, REQ-6-2-3 then creates an Open PR on it.
 * Draft creation uses the other free pair (main, docs-refresh).
 */
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';
import {
  auth as authCopy,
  content as contentCopy,
  errors as errorCopy,
  moduleCopy,
  pulls as pullCopy,
  repo as repoCopy,
} from '../frontend/src/contracts/copy';
import { SEED_ACCOUNT, signIn, uniqueToken } from './helpers';

const OWNER = 'alice-dev';
const REPO = 'acme-docs';
const BASE = `/${OWNER}/${REPO}`;
const LIST = `${BASE}/pulls`;
const COMPARE = `${BASE}/pulls/compare`;
const LAB_BASE = '/alice-dev/protection-lab';
const LAB_PULLS = `${LAB_BASE}/pulls`;
const LAB_BRANCHES = `${LAB_BASE}/settings/branches`;

const SEED_PR = 'Improve onboarding';
const SEED_PR_BODY = 'Make the onboarding flow easier to follow.';
const SEED_PR_COMMENT = 'Please add the onboarding notes before merging.';
const SEED_DRAFT = 'Draft onboarding update';
const LAB_PR = 'Update policy documentation';

async function signInAs(page: Page, username: string) {
  await signIn(page, username, 'Valid-password-123!');
}

test.describe('REQ-6-1 branch protection', () => {
  test('an Admin creates the unique main rule from Settings → Branches and it persists', async ({ page }) => {
    await signInAs(page, SEED_ACCOUNT.username);
    await page.goto(`${LAB_BASE}/settings`);
    await expect(page.getByRole('link', { name: repoCopy.settings })).toBeVisible();

    // Settings link → Branches link.
    await page.getByRole('link', { name: pullCopy.branches }).click();
    await expect(page).toHaveURL(new RegExp(`${LAB_BASE}/settings/branches$`));
    await expect(page.getByRole('heading', { name: pullCopy.branches })).toBeVisible();

    // The rule form opens from the button (no rule exists before creation).
    await expect(page.locator('[data-rule-branch]')).toHaveCount(0);
    await page.getByRole('button', { name: pullCopy.addBranchProtectionRule }).click();
    await page.getByLabel(pullCopy.branchNamePattern).fill('main');
    await page.getByRole('checkbox', { name: pullCopy.require1Approval }).check();
    await page.getByRole('checkbox', { name: pullCopy.requireStatusCheckTest }).check();
    await page.getByRole('button', { name: pullCopy.create }).click();

    const rule = page.locator('[data-rule-branch="main"]');
    await expect(rule).toHaveCount(1);
    await expect(rule).toContainText('main');
    await expect(rule).toContainText(pullCopy.approvalSummary);
    await expect(rule).toContainText(pullCopy.requireStatusCheckTest);

    await page.reload();
    await expect(page.locator('[data-rule-branch]')).toHaveCount(1);
    await expect(page.locator('[data-rule-branch="main"]')).toContainText(pullCopy.approvalSummary);
  });

  test('a readable non-Admin reaches Branches but has no rule control and the API rejects the save', async ({ page }) => {
    await signInAs(page, 'dave-reader');
    await page.goto(LAB_BRANCHES);
    await expect(page.getByRole('heading', { name: pullCopy.branches })).toBeVisible();
    await expect(page.getByRole('button', { name: pullCopy.addBranchProtectionRule })).toHaveCount(0);

    const denied = await page.request.put(`/api/repos/alice-dev/protection-lab/rules/branches`, {
      data: { branchName: 'main', requireApproval: true, requireCheckTest: true },
    });
    expect(denied.status()).toBe(403);

    // The rejected save left no rule behind, and the page mirrors that state.
    const rules = await page.request.get(`/api/repos/alice-dev/protection-lab/rules/branches`);
    expect((await rules.json()).rules).toEqual([]);
    await expect(page.locator('[data-rule-branch]')).toHaveCount(0);
  });

  test('an Admin sets test: success in the Checks area and it persists for the compare commit', async ({ page }) => {
    await signInAs(page, SEED_ACCOUNT.username);
    await page.goto(LAB_PULLS);
    await page.getByRole('link', { name: LAB_PR }).click();

    // The Checks area is available on arrival and starts pending.
    await expect(page.getByText('test: pending')).toBeVisible();
    await page.getByRole('combobox', { name: pullCopy.testStatus }).selectOption('success');
    await page.getByRole('button', { name: pullCopy.save }).click();

    await expect(page.getByText('test: success')).toBeVisible();
    await expect(page.locator('[data-check-setter]')).toHaveText(SEED_ACCOUNT.username);

    await page.reload();
    await expect(page.getByText('test: success')).toBeVisible();

    // The saved verdict belongs to the PR's current compare commit.
    const detail = await (await page.request.get(`/api/repos/alice-dev/protection-lab/pulls/1`)).json();
    const check = await (await page.request.get(`/api/repos/alice-dev/protection-lab/pulls/1/checks`)).json();
    expect(check.check.status).toBe('success');
    expect(check.check.compareCommitId).toBe(detail.pull.currentCompareCommitId);
  });

  test('only an Admin can change the test status', async ({ page }) => {
    await signInAs(page, 'dave-reader');
    await page.goto(`${LAB_PULLS}/1`);
    await expect(page.getByText('test: pending')).toBeVisible();
    await expect(page.getByRole('combobox', { name: pullCopy.testStatus })).toHaveCount(0);

    const denied = await page.request.put('/api/repos/alice-dev/protection-lab/pulls/1/checks/test', {
      data: { status: 'success' },
    });
    expect(denied.status()).toBe(403);
  });
});

test.describe('REQ-6-2-1 pull request list', () => {
