test.describe('REQ-6-2-2 branch comparison', () => {
  test('a Write collaborator compares main → feature-search and it stays read-only', async ({ page }) => {
    await signInAs(page, SEED_ACCOUNT.username);
    await page.goto(LIST);

    const before = await (await page.request.get(`/api/repos/alice-dev/acme-docs/pulls`)).json();

    await page.getByRole('link', { name: pullCopy.newPullRequest }).click();
    await expect(page).toHaveURL(new RegExp('/pulls/compare$'));

    await page.getByRole('combobox', { name: contentCopy.base }).selectOption('main');
    await page.getByRole('combobox', { name: contentCopy.compare }).selectOption('feature-search');
    await page.getByRole('button', { name: contentCopy.compareChanges }).click();

    // Both branch names, comparable commits, the known changed file and a diff summary.
    await expect(page.getByRole('combobox', { name: contentCopy.base })).toHaveValue('main');
    await expect(page.getByRole('combobox', { name: contentCopy.compare })).toHaveValue('feature-search');
    const commitSummary = page.getByRole('heading', { name: contentCopy.commits });
    await expect(commitSummary).toBeVisible();
    await expect(commitSummary.getByText('2', { exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: 'src/search.ts' })).toBeVisible();
    await expect(page.getByText('3 files, 7 additions, 0 deletions')).toBeVisible();
    await expect(page.getByRole('button', { name: pullCopy.createPullRequest })).toBeEnabled();

    // Changing compare to the same branch immediately means "No changes" and no entry.
    await page.getByRole('combobox', { name: contentCopy.compare }).selectOption('main');
    await expect(page.getByText(contentCopy.noChanges)).toBeVisible();
    await expect(page.getByRole('button', { name: pullCopy.createPullRequest })).toBeDisabled();
    await expect(page.getByRole('button', { name: pullCopy.createDraftPullRequest })).toBeDisabled();

    // Comparison is read-only.
    const after = await (await page.request.get(`/api/repos/alice-dev/acme-docs/pulls`)).json();
    expect(after.pulls.length).toBe(before.pulls.length);
  });

  test('selecting the same branch in both selects needs no Compare changes click', async ({ page }) => {
    await signInAs(page, SEED_ACCOUNT.username);
    await page.goto(COMPARE);
    await page.getByRole('combobox', { name: contentCopy.base }).selectOption('main');
    await page.getByRole('combobox', { name: contentCopy.compare }).selectOption('main');
    await expect(page.getByText(contentCopy.noChanges)).toBeVisible();
    await expect(page.getByRole('button', { name: pullCopy.createPullRequest })).toBeDisabled();

    await page.getByRole('button', { name: contentCopy.compareChanges }).click();
    await expect(page.getByText(contentCopy.noChanges)).toBeVisible();
    await expect(page.getByRole('button', { name: pullCopy.createPullRequest })).toBeDisabled();
  });

  test('Read and Triage cannot enter the creation-comparison flow', async ({ page }) => {
    for (const username of ['dave-reader', 'pw-triage']) {
      await signInAs(page, username);
      await page.goto(LIST);
      await expect(page.getByRole('link', { name: pullCopy.newPullRequest })).toHaveCount(0);

      await page.goto(`${COMPARE}?base=main&compare=feature-search`);
      await expect(page.getByRole('button', { name: pullCopy.createPullRequest })).toHaveCount(0);
      await expect(page.getByText(errorCopy.forbidden)).toBeVisible();

      const denied = await page.request.get('/api/repos/alice-dev/acme-docs/pulls/compare?base=main&compare=feature-search');
      expect(denied.status()).toBe(403);
    }
  });
});

