test.describe('REQ-6-2-4 draft pull requests', () => {
  test('a collaborator creates a Draft with a disabled Merge pull request entry', async ({ page }) => {
    const title = uniqueToken('pw-draft');
    await signInAs(page, SEED_ACCOUNT.username);
    await page.goto(`${COMPARE}?base=main&compare=docs-refresh`);

    await page.getByRole('button', { name: pullCopy.createDraftPullRequest }).click();
    await page.getByLabel(pullCopy.title).fill(title);
    await page.getByRole('button', { name: pullCopy.createDraftPullRequest }).click();

    await expect(page.getByRole('heading', { level: 1, name: title })).toBeVisible();
    await expect(page.locator('[data-pr-state="draft"]')).toBeVisible();
    await expect(page.getByRole('button', { name: moduleCopy.mergePullRequest })).toBeDisabled();

    await page.reload();
    await expect(page.locator('[data-pr-state="draft"]')).toBeVisible();

    await page.goto(`${LIST}?state=draft`);
    const row = page.getByRole('listitem').filter({ hasText: title });
    await expect(row.locator('[data-pr-state="draft"]')).toHaveText(pullCopy.draft);
  });

  test('the author moves the seeded Draft to Open and records the activity', async ({ page }) => {
    await signInAs(page, SEED_ACCOUNT.username);
    await page.goto(`${LIST}?state=draft`);
    await page.getByRole('link', { name: SEED_DRAFT }).click();
    await expect(page.locator('[data-pr-state="draft"]')).toBeVisible();

    await page.getByRole('button', { name: pullCopy.readyForReview }).click();

    await expect(page.locator('[data-pr-state="open"]')).toBeVisible();
    await expect(page.locator('[data-pr-state="draft"]')).toHaveCount(0);
    await expect(page.locator('[data-activity-kind="pull_request_ready_for_review"]')).toBeVisible();
    await expect(page.getByRole('heading', { level: 1, name: SEED_DRAFT })).toBeVisible();
    await expect(page.locator('[data-branch-role="base"]')).toHaveText('main');
    await expect(page.locator('[data-branch-role="compare"]')).toHaveText('draft-feature');

