import { api } from '../../api/client';
import { pulls as pullCopy } from '../../contracts/copy';
import type { DiffPayload, ViewerPermission } from '../repo/api';

export type PullState = 'draft' | 'open' | 'closed' | 'merged';

/** Repository role ladder (docs/architecture.md §4) — mirrors the backend order. */
const ROLE_ORDER = ['read', 'triage', 'write', 'maintain', 'admin'];

export function roleAtLeast(role: string | null | undefined, required: string): boolean {
  if (!role) return false;
  return ROLE_ORDER.indexOf(role) >= ROLE_ORDER.indexOf(required);
}

/** PR creation / comparison need Write or above. */
export function canWritePulls(role: string | null | undefined): boolean {
  return roleAtLeast(role, 'write');
}

/** Checks status updates need Admin (REQ-6-1). */
export function isPullAdmin(role: string | null | undefined): boolean {
  return roleAtLeast(role, 'admin');
}

/**
 * Ready for review is Author ∪ Maintain ∪ Admin (REQ-6-2-4); an organisation
 * Owner is an Admin of the organisation's repositories.
 */
export function canSetPullReady(role: string | null | undefined, isAuthor: boolean): boolean {
  return isAuthor || role === 'maintain' || roleAtLeast(role, 'admin');
}

export interface PullSummary {
  id: number;
  number: number;
  title: string;
  body: string;
  state: PullState;
  author: string | null;
  createdAt: string;
  updatedAt: string;
  baseBranch: string | null;
  compareBranch: string | null;
