const encode = (value: string | number) => encodeURIComponent(String(value));
const base = (owner: string, name: string) => `/api/repos/${encode(owner)}/${encode(name)}`;
const pullBase = (owner: string, name: string, number: number) => `${base(owner, name)}/pulls/${encode(number)}`;

export const pullApi = {
  list: (owner: string, name: string, query: PullListQuery = {}) => {
    const params = new URLSearchParams();
    if (query.state) params.set('state', query.state);
    if (query.author) params.set('author', query.author);
    if (query.review) params.set('review', query.review);
    const search = params.toString();
    return api.get<PullListResult>(`${base(owner, name)}/pulls${search ? `?${search}` : ''}`);
  },

  detail: (owner: string, name: string, number: number) =>
    api
      .get<{
        pull: PullSummary;
        checks: CheckState;
        comments: PullComment[];
        activities: PullActivity[];
        reviews: PullReview[];
        viewerPermission: ViewerPermission;
      }>(pullBase(owner, name, number))
      .then((result) => ({
        ...result.pull,
        checks: result.checks,
        comments: result.comments,
        activities: result.activities,
        reviews: result.reviews,
        viewerPermission: result.viewerPermission,
      })),

  compare: (owner: string, name: string, query: { base?: string; compare?: string } = {}) => {
    const params = new URLSearchParams();
    if (query.base) params.set('base', query.base);
    if (query.compare) params.set('compare', query.compare);
    const search = params.toString();
    return api.get<ComparisonResult>(`${base(owner, name)}/pulls/compare${search ? `?${search}` : ''}`);
  },

  create: (
    owner: string,
    name: string,
    input: { title: string; body: string; base: string; compare: string; draft: boolean },
  ) => api.post<{ pull: PullSummary }>(`${base(owner, name)}/pulls`, input).then((result) => result.pull),

  readyForReview: (owner: string, name: string, number: number) =>
    api.post<{ pull: PullSummary }>(`${pullBase(owner, name, number)}/ready`).then((result) => result.pull),

  checks: (owner: string, name: string, number: number) =>
    api.get<{ check: CheckState }>(`${pullBase(owner, name, number)}/checks`).then((result) => result.check),

  setCheck: (owner: string, name: string, number: number, status: string) =>
    api
      .put<{ check: CheckState }>(`${pullBase(owner, name, number)}/checks/test`, { status })
      .then((result) => result.check),

  rules: (owner: string, name: string) => api.get<BranchRulesResult>(`${base(owner, name)}/rules/branches`),

  saveRule: (
    owner: string,
    name: string,
    input: { branchName: string; requireApproval: boolean; requireCheckTest: boolean },
  ) => api.put<{ rule: BranchRule }>(`${base(owner, name)}/rules/branches`, input).then((result) => result.rule),
};

/** Route helpers, kept together so links cannot drift apart. */
export const pullPaths = {
  list: (owner: string, name: string) => `/${owner}/${name}/pulls`,
  compare: (owner: string, name: string, base?: string, compare?: string) => {
    const params = new URLSearchParams();
    if (base) params.set('base', base);
    if (compare) params.set('compare', compare);
    const search = params.toString();
    return `/${owner}/${name}/pulls/compare${search ? `?${search}` : ''}`;
  },
  detail: (owner: string, name: string, number: number, tab?: string) =>
    `/${owner}/${name}/pulls/${number}${tab ? `?tab=${tab}` : ''}`,
  branches: (owner: string, name: string) => `/${owner}/${name}/settings/branches`,
};

/** Human-readable timestamp for timelines and check metadata. */
export function formatPullTimestamp(value: string | null | undefined): string {
  if (!value) return '';
  const iso = value.includes('T') ? value : `${value.replace(' ', 'T')}Z`;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
}

