/**
 * Shared read helper for the modules that must respect a protected branch
 * (M4b Web writes, M6b merge gating): the rule of one exact branch, or null.
 */
export function isBranchProtected(db, repoId, branchName) {
  const row = db
    .prepare('SELECT * FROM branch_protections WHERE repo_id = ? AND branch_name = ?')
    .get(repoId, branchName);
  return row ? serializeRule(row) : null;
}

// --- M6b: inline review comments (REQ-6-3-3) -------------------------------

/** Latest decision of every reviewer on the *current* compare commit (§9.18). */
function latestDecisions(db, pr) {
  const compareCommitId = currentCompareCommitId(db, pr);
  const rows = db
    .prepare(
      `SELECT r.*, u.username AS reviewer FROM reviews r
        LEFT JOIN users u ON u.id = r.reviewer_id
        WHERE r.pr_id = ? AND (r.compare_commit_id IS ?) ORDER BY r.id`,
    )
    .all(pr.id, compareCommitId);
  const latest = new Map();
  for (const row of rows) latest.set(row.reviewer_id, row);
  return [...latest.values()];
}

/** Usernames with a valid (current compare commit, non-author) Approve. */
export function validApprovals(db, pr) {
  return latestDecisions(db, pr)
    .filter((review) => review.decision === 'approve' && Number(review.reviewer_id) !== Number(pr.author_id))
    .map((review) => review.reviewer)
    .filter(Boolean);
}

/**
 * `Outdated` means only one thing (REQ-6-3-3): the comment was created against a
 * compare commit that is no longer the compare branch head. The comment is never
 * relocated; the original path/line/commit are retained.
 */
function serializeReviewComment(comment, currentCommitId) {
  return {
    id: comment.id,
    path: comment.path,
    line: comment.line,
    side: comment.side ?? null,
    body: comment.body,
    author: comment.author ?? null,
    published: comment.published === 1,
    outdated: comment.compare_commit_id !== currentCommitId,
    compareCommitId: comment.compare_commit_id,
    compareCommitShortId: comment.compare_commit_id != null ? shortId(comment.compare_commit_id) : null,
    createdAt: comment.created_at,
  };
}

/**
 * Inline comments of a PR. Everyone sees published comments; the author also sees
 * their own pending drafts, which is what keeps a draft private until the review
 * is submitted (REQ-6-3-3).
 */
export function listReviewComments(db, pr, viewer) {
  const currentCommitId = currentCompareCommitId(db, pr);
  return db
    .prepare(
      `SELECT rc.*, u.username AS author FROM review_comments rc
        LEFT JOIN users u ON u.id = rc.author_id
        WHERE rc.pr_id = ? ORDER BY rc.id`,
    )
    .all(pr.id)
    .filter((row) => row.published === 1 || (viewer != null && Number(viewer.id) === Number(row.author_id)))
    .map((row) => serializeReviewComment(row, currentCommitId));
}

/**
 * The current three-dot diff of the PR (base branch → compare branch head). The
 * inline anchor must be one of its added/deleted lines, so Files changed can
 * render the comment exactly where it was written (REQ-6-3-3).
 */
function currentDiff(db, repo, pr) {
  const base = branchRowById(db, pr.base_branch_id);
  const compare = branchRowById(db, pr.compare_branch_id);
  if (!base || !compare) return null;
  return compareRevisions(db, repo, { base: base.name, compare: compare.name });
}

/** Is `{path,line,side}` one added/deleted line of the current diff? */
function anchorExists(diff, path, line, side) {
  if (!diff) return false;
  const file = diff.files.find((entry) => entry.path === path);
  if (!file) return false;
  return file.lines.some((entry) =>
    side === 'new' ? entry.type === 'added' && entry.newNumber === line : entry.type === 'deleted' && entry.oldNumber === line,
  );
}

/**
 * Add one inline review comment (REQ-6-3-3). `pending: true` stores a draft
 * (`published = 0`) that only its author can read until a review is submitted.
 * Every validation runs before the insert, so a rejected submission leaves no row.
 */
export function createReviewComment(db, repo, pr, user, input = {}) {
  const body = typeof input.body === 'string' ? input.body.trim() : '';
  const path = text(input.path);
  const side = text(input.side);
  const line = Number(input.line);
  const pending = input.pending === true || input.pending === 'true' || input.pending === 1;
  const errors = [];

  if (!body) errors.push(fieldError('comment_required', messages.COMMENT_REQUIRED, 'body'));
  else if (body.length > BODY_MAX) errors.push(fieldError('comment_too_long', messages.COMMENT_TOO_LONG, 'body'));
  if (!REVIEW_COMMENT_SIDES.includes(side)) {
    errors.push(fieldError('review_side_invalid', messages.REVIEW_SIDE_INVALID, 'side'));
  }
  if (!Number.isInteger(line) || line < 1) {
    errors.push(fieldError('review_anchor_invalid', messages.REVIEW_ANCHOR_INVALID, 'line'));
  }
  if (errors.length) throw validationError(errors);

  const compareCommitId = currentCompareCommitId(db, pr);
  if (compareCommitId == null || !anchorExists(currentDiff(db, repo, pr), path, line, side)) {
    throw validationError([fieldError('review_anchor_invalid', messages.REVIEW_ANCHOR_INVALID, 'line')]);
  }

  const comment = db
    .prepare(
      `INSERT INTO review_comments (pr_id, path, compare_commit_id, line, side, body, author_id, published)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?) RETURNING *`,
    )
    .get(pr.id, path, compareCommitId, line, side, body, user.id, pending ? 0 : 1);
  return serializeReviewComment({ ...comment, author: user.username ?? username(db, user.id) }, compareCommitId);
}

// --- M6b: submitted reviews (REQ-6-3-4) -------------------------------------

/**
 * Submit a review (REQ-6-3-4). One transaction: the decision row and the
 * publication of this reviewer's pending drafts of the PR (including drafts whose
 * anchor already went stale — otherwise they would have no publication path).
 */
export function createReview(db, repo, pr, user, input = {}) {
  const decision = text(input.decision);
  const summary = typeof input.summary === 'string' ? input.summary.trim() : '';
  const errors = [];
  if (!REVIEW_DECISIONS.includes(decision)) {
    errors.push(fieldError('review_decision_invalid', messages.REVIEW_DECISION_INVALID, 'decision'));
  }
  if (summary.length > BODY_MAX) {
    errors.push(fieldError('review_summary_too_long', messages.DESCRIPTION_TOO_LONG, 'summary'));
  }
  if (errors.length) throw validationError(errors);

  const compareCommitId = currentCompareCommitId(db, pr);
  if (compareCommitId == null) {
    throw validationError([fieldError('check_branch_missing', messages.CHECK_BRANCH_MISSING, 'decision')]);
  }

  return transact(db, () => {
    const published = db
      .prepare('UPDATE review_comments SET published = 1 WHERE pr_id = ? AND author_id = ? AND published = 0')
      .run(pr.id, user.id).changes;
    const review = db
      .prepare(
        `INSERT INTO reviews (pr_id, reviewer_id, decision, summary, compare_commit_id)
         VALUES (?, ?, ?, ?, ?) RETURNING *`,
      )
      .get(pr.id, user.id, decision, summary, compareCommitId);
    return {
      review: {
        id: review.id,
        reviewer: user.username ?? username(db, user.id),
        decision: review.decision,
        summary: review.summary,
        compareCommitId: review.compare_commit_id,
        stale: false,
        createdAt: review.created_at,
      },
      publishedComments: published,
    };
  });
}

// --- M6b: reviewer requests (REQ-6-4) ---------------------------------------

/** Requested reviewers of one PR (pending-review relationship, not a decision). */
export function listPullReviewers(db, pr) {
  return db
    .prepare(
      `SELECT rr.*, u.username AS username, rb.username AS requested_by
         FROM pull_request_reviewers rr
         JOIN users u ON u.id = rr.user_id
         LEFT JOIN users rb ON rb.id = rr.requested_by
        WHERE rr.pr_id = ? ORDER BY rr.created_at, u.username COLLATE NOCASE`,
    )
    .all(pr.id)
    .map((row) => ({ username: row.username, requestedBy: row.requested_by, createdAt: row.created_at }));
}

/**
 * Request one reviewer (REQ-6-4). The candidate must have Write or above on the
 * repository and must not be the PR author; requesting twice is idempotent, and
 * the relationship never creates a review by itself.
 */
export function addPullReviewer(db, repo, pr, user, rawUsername) {
  const target = text(rawUsername);
  const candidate = db.prepare('SELECT * FROM users WHERE username = ?').get(target);
  const role = candidate ? effectiveRepoRole(db, candidate, repo) : null;
  if (!candidate || Number(candidate.id) === Number(pr.author_id) || !role || (role !== 'write' && role !== 'maintain' && role !== 'admin')) {
    throw validationError([fieldError('reviewer_not_eligible', messages.REVIEWER_NOT_ELIGIBLE, 'username')]);
  }
  db.prepare(
    `INSERT INTO pull_request_reviewers (pr_id, user_id, requested_by)
     VALUES (?, ?, ?)
     ON CONFLICT (pr_id, user_id) DO NOTHING`,
  ).run(pr.id, candidate.id, user.id);
  return listPullReviewers(db, pr);
}

/**
 * Remove a reviewer request (REQ-6-4). Only the relationship row is deleted: the
 * reviewer's reviews, comments and activities are preserved and their effective
 * decision is unchanged. Removing an absent request is a no-op.
 */
export function removePullReviewer(db, pr, rawUsername) {
  const target = text(rawUsername);
  const candidate = db.prepare('SELECT * FROM users WHERE username = ?').get(target);
  if (candidate) {
    db.prepare('DELETE FROM pull_request_reviewers WHERE pr_id = ? AND user_id = ?').run(pr.id, candidate.id);
  }
  return listPullReviewers(db, pr);
}

// --- M6b: merge gating and transactional merge (REQ-6-5) --------------------

function treeOfCommit(db, commitId) {
  if (commitId == null) return {};
  const row = db.prepare('SELECT tree_json FROM commits WHERE id = ?').get(commitId);
  return readTree(row?.tree_json);
}

/**
 * Line-free three-way merge of the PR (docs/architecture.md §9.2). A path both
 * sides changed differently is a conflict; otherwise the changed side wins.
 */
function mergeTrees(ancestorTree, baseTree, compareTree) {
  const paths = new Set([...Object.keys(baseTree), ...Object.keys(compareTree)]);
  const merged = {};
  const conflicts = [];
  for (const path of paths) {
    const ancestor = ancestorTree[path];
    const base = baseTree[path];
    const compare = compareTree[path];
    const baseChanged = base !== ancestor;
    const compareChanged = compare !== ancestor;
    if (baseChanged && compareChanged && base !== compare) {
      conflicts.push(path);
      if (base !== undefined) merged[path] = base;
    } else if (compareChanged) {
      if (compare !== undefined) merged[path] = compare;
    } else if (base !== undefined) {
      merged[path] = base;
    }
  }
  return { merged, conflicts };
}

/**
 * Merge-eligibility snapshot of a PR (REQ-6-5). Computed server-side from the
 * *current* state every time it is read, and the frontend only renders it: the
 * button is visible and disabled while `eligible` is false, and `reasons[]` names
 * every unmet condition so nothing has to be discovered by clicking.
 */
export function mergeGate(db, repo, pr) {
  const baseBranch = branchRowById(db, pr.base_branch_id);
  const baseHead = baseBranch?.head_commit_id ?? null;
  const compareHead = currentCompareCommitId(db, pr);
  const rule = baseBranch ? isBranchProtected(db, pr.repo_id, baseBranch.name) : null;
  const requireApproval = Boolean(rule?.requireApproval);
  const requireCheckTest = Boolean(rule?.requireCheckTest);
  const check = getCheck(db, pr);
  const approvals = validApprovals(db, pr);
  const changesRequested = reviewState(db, pr) === 'changes_requested';
  const ancestorId = baseHead != null && compareHead != null ? mergeBase(db, baseHead, compareHead) : null;
  const { conflicts } = mergeTrees(treeOfCommit(db, ancestorId), treeOfCommit(db, baseHead), treeOfCommit(db, compareHead));
  const noChanges =
    baseHead == null || compareHead == null || ancestorsOrSelf(db, baseHead).has(compareHead);

  const reasons = [];
  if (pr.state !== 'open') reasons.push({ code: 'not_open', message: messages.PULL_NOT_OPEN });
  if (changesRequested) {
    reasons.push({ code: 'changes_requested', message: messages.PULL_MERGE_CHANGES_REQUESTED });
  }
  if (conflicts.length) reasons.push({ code: 'conflicts', message: messages.PULL_MERGE_CONFLICTS });
  if (requireApproval && approvals.length === 0) {
    reasons.push({ code: 'approval_required', message: messages.REVIEW_REQUIRED_BY_BRANCH_PROTECTION });
  }
  if (requireCheckTest && check.status !== 'success') {
    reasons.push({ code: 'check_required', message: messages.PULL_MERGE_CHECK_REQUIRED });
  }
  if (noChanges) reasons.push({ code: 'no_changes', message: messages.PULL_MERGE_NO_CHANGES });

  return {
    eligible: reasons.length === 0,
    protected: Boolean(rule),
    requireApproval,
    requireCheckTest,
    approval: { satisfied: approvals.length > 0, count: approvals.length, reviewers: approvals },
    check: { satisfied: check.status === 'success', status: check.status },
    conflicts: conflicts.length > 0,
    conflictPaths: conflicts,
    changesRequested,
    noChanges,
    reasons,
  };
}

function mergeRejection(gate) {
  const [reason] = gate.reasons;
  return validationError([fieldError(reason.code, reason.message, 'merge')]);
}

/**
 * Merge an eligible PR (REQ-6-5). Everything is reread inside one transaction:
 * the PR state, the target-branch head and compare head at merge time, the
 * protection rules, the checks and the reviews. A failure rolls back completely —
 * neither the target branch nor the PR changes. The merge commit has two parents
 * (`commits.parent_id` = target head *and* both `commit_parents` rows, §9.2) and
 * its `commit_files` are the first-parent change set, so the §7.2 consistency
 * assertion keeps holding for every commit. The compare branch is never touched,
 * and the merge does not go through the Web write path (which rightly refuses a
 * protected branch, while merging into one is the protected branch's purpose).
 */
export function mergePull(db, repo, pr, user) {
  const preflight = mergeGate(db, repo, pr);
  if (!preflight.eligible) throw mergeRejection(preflight);

  return transact(db, () => {
    const fresh = getPullById(db, pr.id);
    const gate = mergeGate(db, repo, fresh);
    if (!gate.eligible) throw mergeRejection(gate);

    const baseBranch = branchRowById(db, fresh.base_branch_id);
    const compareBranch = branchRowById(db, fresh.compare_branch_id);
    const baseHead = baseBranch.head_commit_id;
    const compareHead = currentCompareCommitId(db, fresh);
    const ancestorId = mergeBase(db, baseHead, compareHead);
    const baseTree = treeOfCommit(db, baseHead);
    const { merged } = mergeTrees(treeOfCommit(db, ancestorId), baseTree, treeOfCommit(db, compareHead));

    const commit = db
      .prepare(
        `INSERT INTO commits (repo_id, parent_id, author_id, message, tree_json)
         VALUES (?, ?, ?, ?, ?) RETURNING *`,
      )
      .get(
        repo.id,
        baseHead,
        user.id,
        `Merge pull request #${fresh.number} from ${compareBranch.name}`,
        JSON.stringify(merged),
      );
    const insertParent = db.prepare(
      'INSERT INTO commit_parents (commit_id, parent_commit_id, position) VALUES (?, ?, ?)',
    );
    insertParent.run(commit.id, baseHead, 0);
    insertParent.run(commit.id, compareHead, 1);
    const insertFile = db.prepare(
      `INSERT INTO commit_files (commit_id, path, status, additions, deletions) VALUES (?, ?, ?, ?, ?)`,
    );
    for (const file of diffTrees(baseTree, merged)) {
      insertFile.run(commit.id, file.path, file.status, file.additions, file.deletions);
    }
    db.prepare('UPDATE branches SET head_commit_id = ? WHERE id = ?').run(commit.id, baseBranch.id);
    db.prepare(
      `UPDATE pull_requests SET state = 'merged', merged_commit_id = ?, updated_at = datetime('now') WHERE id = ?`,
    ).run(commit.id, fresh.id);
    insertActivity(db, {
      kind: 'pull_request_merged',
      actorId: user.id,
      subjectType: 'pull_request',
      subjectId: fresh.id,
      payload: { number: fresh.number, mergedCommitId: commit.id, mergeCommitShortId: shortId(commit.id) },
    });
    return getPullById(db, fresh.id);
  });
}

/** Merged PRs are terminal: close/reopen/merge are all rejected (REQ-6-5/6-6). */
export function ensureNotMerged(pr) {
  if (pr.state === 'merged') {
    throw validationError([fieldError('pull_merged_terminal', messages.PULL_MERGED_TERMINAL, 'state')]);
  }
}

/**
 * Close an Open or Draft PR without merging (REQ-6-6). It only writes the state
 * and the timeline activity: no branch, review, comment or diff is touched.
 */
export function closePull(db, pr, user) {
  ensureNotMerged(pr);
  if (pr.state !== 'open' && pr.state !== 'draft') {
    throw validationError([fieldError('pull_not_open', messages.PULL_NOT_OPEN, 'state')]);
  }
  return transact(db, () => {
    db.prepare(`UPDATE pull_requests SET state = 'closed', updated_at = datetime('now') WHERE id = ?`).run(pr.id);
    insertActivity(db, {
      kind: 'pull_request_closed',
      actorId: user.id,
      subjectType: 'pull_request',
      subjectId: pr.id,
      payload: { number: pr.number },
    });
    return getPullById(db, pr.id);
  });
}

/** Reopen a Closed PR (REQ-6-6). Merged stays terminal. */
export function reopenPull(db, pr, user) {
  ensureNotMerged(pr);
  if (pr.state !== 'closed') {
    throw validationError([fieldError('pull_not_open', messages.PULL_NOT_OPEN, 'state')]);
  }
  return transact(db, () => {
    db.prepare(`UPDATE pull_requests SET state = 'open', updated_at = datetime('now') WHERE id = ?`).run(pr.id);
    insertActivity(db, {
      kind: 'pull_request_reopened',
      actorId: user.id,
      subjectType: 'pull_request',
      subjectId: pr.id,
      payload: { number: pr.number },
    });
    return getPullById(db, pr.id);
  });
}

/** Merger/time/result of a Merged PR, derived from the merge activity (REQ-6-5). */
export function mergedInfo(db, pr) {
  if (pr.state !== 'merged' || pr.merged_commit_id == null) return null;
  const activity = db
    .prepare(
      `SELECT a.*, u.username AS actor FROM activities a
        LEFT JOIN users u ON u.id = a.actor_id
        WHERE a.subject_type = 'pull_request' AND a.subject_id = ? AND a.kind = 'pull_request_merged'
        ORDER BY a.id DESC LIMIT 1`,
    )
    .get(pr.id);
  return {
    commitId: pr.merged_commit_id,
    shortId: shortId(pr.merged_commit_id),
    merger: activity?.actor ?? null,
    at: activity?.created_at ?? pr.updated_at,
  };
}

