import { useEffect, useMemo, useState } from 'react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { Button } from '../../components/Button';
import { Dialog } from '../../components/Dialog';
import { RadioGroup } from '../../components/RadioGroup';
import { SegmentedNav } from '../../components/SegmentedNav';
import { TextAreaField } from '../../components/TextField';
import { useAuth } from '../../auth/AuthContext';
import {
  auth as authCopy,
  content as contentCopy,
  errors as errorCopy,
  issues as issueCopy,
  moduleCopy,
  pulls as pullCopy,
} from '../../contracts/copy';
import { MetadataPicker } from '../issues/IssueControls';
import { DiffView } from '../repo/DiffView';
import { RepoHeader, RepoNav } from '../repo/RepoHeader';
import { RepositoryMissing } from '../repo/RepositoryMissing';
import { repoApi } from '../repo/api';
import type { DiffFile, DiffLine, DiffPayload } from '../repo/api';
import { useRepository } from '../repo/useRepository';
import { PullChecks } from './PullChecks';
import {
  canClosePull,
  canManagePullReviewers,
  canMergePull,
  canReviewPull,
  canSetPullReady,
  formatPullTimestamp,
  isPullAdmin,
  PULL_STATE_LABELS,
  pullApi,
  pullPaths,
} from './api';
import type {
  CheckState,
  MergeGate,
  PullDetail,
  PullReview,
  PullReviewComment,
  PullReviewer,
  PullState,
} from './api';

const TABS = ['conversation', 'commits', 'files_changed', 'checks'] as const;
type Tab = (typeof TABS)[number];

const ACTIVITY_LABELS: Record<string, string> = {
  pull_request_opened: pullCopy.openedActivity,
  pull_request_ready_for_review: pullCopy.readyForReviewActivity,
  pull_request_closed: pullCopy.closedActivity,
  pull_request_reopened: pullCopy.reopenedActivity,
  pull_request_merged: pullCopy.mergedActivity,
};

const REVIEW_LABELS: Record<string, string> = {
  approve: pullCopy.approved,
  request_changes: pullCopy.changesRequested,
  comment: issueCopy.comment,
};

/** Anchor identity of one inline comment: path + side + line (REQ-6-3-3). */
function anchorKey(path: string, side: string | null, line: number | null): string {
  return `${path}\u0000${side ?? ''}\u0000${line ?? ''}`;
}

/** Reviews summary of the right sidebar; newest decision last (REQ-6-3-4). */
function ReviewsSummary({ reviews }: { reviews: PullReview[] }) {
  return (
    <section className="app-card p-3" data-testid="pull-reviews">
      <h2 className="m-0 text-sm font-600">{pullCopy.reviews}</h2>
      {reviews.length ? (
        <ul className="m-0 mt-2 flex list-none flex-col gap-2 p-0">
          {reviews.map((review) => (
            <li key={review.id} className="text-sm">
              <p className="m-0">
                <span className="font-600">{review.reviewer}</span>{' '}
                <span data-review-decision={review.decision}>{REVIEW_LABELS[review.decision] ?? review.decision}</span>
                {review.stale ? <span className="badge ml-1">{pullCopy.outdated}</span> : null}
              </p>
              <time className="text-xs text-muted" dateTime={review.createdAt}>
                {formatPullTimestamp(review.createdAt)}
              </time>
              {review.summary ? <p className="m-0 mt-1 whitespace-pre-wrap">{review.summary}</p> : null}
            </li>
          ))}
        </ul>
      ) : (
        <p className="m-0 mt-2 text-sm text-muted">{pullCopy.noReviews}</p>
      )}
    </section>
  );
}

/**
 * Reviewers area of the right sidebar (REQ-6-4). The picker reuses the shared
 * `MetadataPicker`: trigger named exactly `Reviewers`, a plain textbox named
 * `Search`, option named exactly after the username, saving immediately without a
 * Save action. Each requested reviewer has a `Remove <username>` button that also
 * saves immediately, with no confirmation step.
 */
function ReviewersPanel({
  reviewers,
  candidates,
  canManage,
  busy,
  onRequest,
  onRemove,
}: {
  reviewers: PullReviewer[];
  candidates: Array<{ username: string; role: string | null }>;
  canManage: boolean;
  busy: boolean;
  onRequest: (username: string) => void;
  onRemove: (username: string) => void;
}) {
  const requested = new Set(reviewers.map((reviewer) => reviewer.username));
  const options = candidates
    .filter((candidate) => candidate.role === 'write' || candidate.role === 'maintain' || candidate.role === 'admin')
    .filter((candidate) => !requested.has(candidate.username))
    .map((candidate) => ({ value: candidate.username, label: candidate.username, selected: false }));

  return (
    <section className="app-card p-3" data-testid="pull-reviewers">
      <div className="flex items-center justify-between gap-2">
        <h2 className="m-0 text-sm font-600">{pullCopy.reviewers}</h2>
        {canManage ? (
          <MetadataPicker
            buttonLabel={pullCopy.reviewers}
            panelTestId="reviewers-picker"
            searchLabel={pullCopy.reviewersSearch}
            options={options}
            busy={busy}
            onSelect={onRequest}
          />
        ) : null}
      </div>
      {reviewers.length ? (
        <ul className="m-0 mt-2 flex list-none flex-col gap-1 p-0">
          {reviewers.map((reviewer) => (
            <li key={reviewer.username} className="flex items-center justify-between gap-2 text-sm">
              <span>{reviewer.username}</span>
              {canManage ? (
                <Button variant="ghost" disabled={busy} onClick={() => onRemove(reviewer.username)}>
                  {pullCopy.removeReviewer(reviewer.username)}
                </Button>
              ) : null}
            </li>
          ))}
        </ul>
      ) : (
        <p className="m-0 mt-2 text-sm text-muted">{pullCopy.noReviewers}</p>
      )}
    </section>
  );
}

/**
 * Merge area (REQ-6-5). The button is visible and disabled while the server-side
 * gate reports unmet conditions, each shown verbatim before any click; when the PR
 * is eligible, `Merge pull request` opens the single supported method
 * (`Create a merge commit`) and `Confirm merge`. A Merged PR shows the merger,
 * time and resulting commit instead of any merge control.
 */
function MergeArea({
  gate,
  merged,
  canMerge,
  busy,
  onMerge,
}: {
  gate: MergeGate;
  merged: PullDetail['merged'];
  canMerge: boolean;
  busy: boolean;
  onMerge: () => void;
}) {
  if (merged) {
    return (
      <div className="mt-2 text-sm" data-testid="pull-merged">
        <p className="m-0">
          <span className="badge" data-pr-merged="true">
            {pullCopy.merged}
          </span>{' '}
          <span className="font-600" data-merged-by>
            {merged.merger}
          </span>{' '}
          <time className="text-muted" dateTime={merged.at}>
            {formatPullTimestamp(merged.at)}
          </time>
        </p>
        <p className="m-0 mt-1 text-muted" data-merged-commit>
          {pullCopy.mergedCommit}: {merged.shortId}
        </p>
      </div>
    );
  }
  if (!canMerge) return null;
  if (gate.eligible) {
    return (
      <Button variant="primary" disabled={busy} onClick={onMerge}>
        {moduleCopy.mergePullRequest}
      </Button>
    );
  }
  return (
    <span className="inline-flex flex-wrap items-center gap-2">
      <Button disabled>{moduleCopy.mergePullRequest}</Button>
      {gate.reasons.map((reason) => (
        <span key={reason.code} className="text-xs text-danger" data-merge-reason={reason.code}>
          {reason.message}
        </span>
      ))}
    </span>
  );
}

/** One inline comment card: author, time, body and the `Pending review` marker. */
function InlineCommentCard({ comment }: { comment: PullReviewComment }) {
  return (
    <div className="app-card mb-1 p-2 text-sm" data-inline-comment={comment.id}>
      <p className="m-0">
        <span className="font-600">{comment.author}</span>{' '}
        <time className="text-xs text-muted" dateTime={comment.createdAt}>
          {formatPullTimestamp(comment.createdAt)}
        </time>
        {!comment.published ? <span className="badge ml-1">{pullCopy.pendingReview}</span> : null}
        {comment.outdated ? <span className="badge ml-1">{pullCopy.outdated}</span> : null}
      </p>
      <p className="m-0 mt-1 whitespace-pre-wrap">{comment.body}</p>
    </div>
  );
}

/**
 * PR detail page (REQ-6-1 checks area, REQ-6-2-4 draft lifecycle, REQ-6-3-1/6-3-2
 * Conversation / Commits / Files changed / Checks, plus M6b REQ-6-3-3 inline
 * comments, REQ-6-3-4 reviews, REQ-6-4 reviewers, REQ-6-5 merge and REQ-6-6
 * close/reopen).
 *
 * All four views read the same persisted PR number; Conversation, Commits, Files
 * changed and Checks are navigation links (`?tab=`). Permission-dependent controls
 * are absent (not disabled) for users the requirement excludes — the server rejects
 * independently — while the merge control stays visible and disabled when only the
 * merge conditions are unmet.
 */
export function PullDetailPage() {
  const params = useParams();
  const owner = params.owner ?? '';
  const name = params.repo ?? '';
  const number = Number.parseInt(params.number ?? '', 10);
  const repositoryState = useRepository(owner, name);
  const { user } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const rawTab = searchParams.get('tab') ?? 'conversation';
  const tab: Tab = (TABS as readonly string[]).includes(rawTab) ? (rawTab as Tab) : 'conversation';

  const [detail, setDetail] = useState<PullDetail | null>(null);
  const [missing, setMissing] = useState(false);
  const [diff, setDiff] = useState<DiffPayload | null>(null);
  const [candidates, setCandidates] = useState<Array<{ username: string; role: string | null }>>([]);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // Inline comment editor (REQ-6-3-3): one editor at a time, mounted only while
  // an anchor is active, so the `Comment` label never collides with the review form.
  const [commentTarget, setCommentTarget] = useState<{ path: string; line: number; side: 'new' | 'old' } | null>(
    null,
  );
  const [commentBody, setCommentBody] = useState('');
  // Review form (REQ-6-3-4): a single dialog, mutually exclusive with the editor.
  const [reviewOpen, setReviewOpen] = useState(false);
  const [reviewDecision, setReviewDecision] = useState<'comment' | 'approve' | 'request_changes'>('comment');
  const [reviewSummary, setReviewSummary] = useState('');
  const [mergeOpen, setMergeOpen] = useState(false);

  useEffect(() => {
    if (repositoryState.status !== 'ready' || !Number.isFinite(number)) return undefined;
    let active = true;
    pullApi
      .detail(owner, name, number)
      .then((value) => {
        if (!active) return;
        setDetail(value);
        setMissing(false);
      })
      .catch(() => {
        if (active) setMissing(true);
      });
    return () => {
      active = false;
    };
  }, [owner, name, number, repositoryState.status, user?.id]);

  // Commits / Files changed come from the viewer-readable M4a compare endpoint
  // with the PR's branch handles (docs/architecture.md §7.2, Issue #9 #235 §3).
  useEffect(() => {
    if (!detail || (tab !== 'commits' && tab !== 'files_changed')) return undefined;
    if (!detail.baseBranch || !detail.compareBranch) return undefined;
    let active = true;
    repoApi
      .compare(owner, name, { base: detail.baseBranch, compare: detail.compareBranch })
      .then((payload) => {
        if (active) setDiff(payload);
      })
      .catch(() => {
        if (active) setDiff(null);
      });
    return () => {
      active = false;
    };
  }, [tab, detail, owner, name]);

  const role = detail?.viewerPermission.repository ?? null;
  const isAuthor = Boolean(user?.username) && user?.username === detail?.author;
  const canManageReviewers = detail ? canManagePullReviewers(role, isAuthor, detail.state) : false;

  // Candidate reviewers reuse GET .../assignable-users (no new endpoint); the
  // server re-validates on POST and is the final authority (REQ-6-4).
  useEffect(() => {
    if (!detail || !canManageReviewers) return undefined;
    let active = true;
    pullApi
      .assignableUsers(owner, name)
      .then((users) => {
        if (active) setCandidates(users);
      })
      .catch(() => {
        if (active) setCandidates([]);
      });
    return () => {
      active = false;
    };
  }, [detail, canManageReviewers, owner, name]);

  const commentsByAnchor = useMemo(() => {
    const map = new Map<string, PullReviewComment[]>();
    for (const comment of detail?.reviewComments ?? []) {
      if (comment.outdated) continue;
      const key = anchorKey(comment.path, comment.side, comment.line);
      const list = map.get(key) ?? [];
      list.push(comment);
      map.set(key, list);
    }
    return map;
  }, [detail?.reviewComments]);

  if (repositoryState.status === 'loading') {
    return (
      <div className="page-shell">
        <p className="text-muted">Loading…</p>
      </div>
    );
  }
  if (repositoryState.status === 'missing') return <RepositoryMissing owner={owner} name={name} />;
  if (missing) {
    return (
      <div className="page-shell">
        <RepoHeader repository={repositoryState.repository} />
        <h1 className="page-title mt-4">{pullCopy.pullNotFound}</h1>
        <Link className="text-accent" to={pullPaths.list(owner, name)}>
          {pullCopy.backToPulls}
        </Link>
      </div>
    );
  }
  if (!detail) {
    return (
      <div className="page-shell">
        <p className="text-muted">Loading…</p>
      </div>
    );
  }

  const repository = repositoryState.repository;
  const canReady = detail.state === 'draft' && canSetPullReady(role, isAuthor);
  const canReview = canReviewPull(role, isAuthor, detail.state);
  const canMerge = canMergePull(role) && detail.state === 'open' && detail.state !== 'merged';
  const canClose =
    canClosePull(role, isAuthor) && (detail.state === 'open' || detail.state === 'draft' || detail.state === 'closed');
  const canReopen = canClosePull(role, isAuthor) && detail.state === 'closed';

  const setTab = (next: Tab) => {
    const params2 = new URLSearchParams(searchParams);
    if (next === 'conversation') params2.delete('tab');
    else params2.set('tab', next);
    setSearchParams(params2);
  };

  const runAction = async (action: () => Promise<PullDetail>) => {
    setBusy(true);
    setActionError(null);
    try {
      setDetail(await action());
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown.message : errorCopy.unknown);
    } finally {
      setBusy(false);
    }
  };

  const ready = () => runAction(() => pullApi.readyForReview(owner, name, detail.number));

  const submitComment = async (pending: boolean) => {
    if (!commentTarget || !commentBody.trim()) return;
    setBusy(true);
    setActionError(null);
    try {
      setDetail(
        await pullApi.addReviewComment(owner, name, detail.number, {
          ...commentTarget,
          body: commentBody,
          pending,
        }),
      );
      setCommentTarget(null);
      setCommentBody('');
    } catch (thrown) {
      // A rejected submission leaves no partial comment on screen.
      setActionError(thrown instanceof Error ? thrown.message : errorCopy.unknown);
    } finally {
      setBusy(false);
    }
  };

  const submitReview = async () => {
    setBusy(true);
    setActionError(null);
    try {
      setDetail(
        await pullApi.submitReview(owner, name, detail.number, {
          decision: reviewDecision,
          summary: reviewSummary,
        }),
      );
      setReviewOpen(false);
      setReviewSummary('');
      setReviewDecision('comment');
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown.message : errorCopy.unknown);
    } finally {
      setBusy(false);
    }
  };

  const confirmMerge = async () => {
    setBusy(true);
    setActionError(null);
    try {
      setDetail(await pullApi.merge(owner, name, detail.number));
      setMergeOpen(false);
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown.message : errorCopy.unknown);
    } finally {
      setBusy(false);
    }
  };

  const requestReviewer = async (username: string) => {
    setBusy(true);
    setActionError(null);
    try {
      setDetail(await pullApi.requestReviewer(owner, name, detail.number, username));
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown.message : errorCopy.unknown);
    } finally {
      setBusy(false);
    }
  };

  const removeReviewer = (username: string) => runAction(() => pullApi.removeReviewer(owner, name, detail.number, username));

  const onCheckChanged = (check: CheckState) => setDetail((current) => (current ? { ...current, checks: check } : current));

  // Inline comment entries (published) join the Conversation timeline; Outdated
  // ones are marked there instead of being relocated in the diff.
  const timeline = [
    ...detail.activities.map((activity) => ({
      key: `activity-${activity.id}`,
      createdAt: activity.createdAt,
      id: activity.id,
      kind: 'activity' as const,
      activityKind: activity.kind,
      actor: activity.actor,
      label: ACTIVITY_LABELS[activity.kind] ?? activity.kind,
      body: null as string | null,
      badge: null as string | null,
    })),
    ...detail.comments.map((comment) => ({
      key: `comment-${comment.id}`,
      createdAt: comment.createdAt,
      id: comment.id,
      kind: 'comment' as const,
      activityKind: undefined,
      actor: comment.author,
      label: null as string | null,
      body: comment.body,
      badge: null as string | null,
    })),
    ...detail.reviews.map((review) => ({
      key: `review-${review.id}`,
      createdAt: review.createdAt,
      id: review.id,
      kind: 'review' as const,
      activityKind: undefined,
      actor: review.reviewer,
      label: REVIEW_LABELS[review.decision] ?? review.decision,
      body: review.summary || null,
      badge: review.stale ? pullCopy.outdated : null,
    })),
    ...detail.reviewComments.map((comment) => ({
      key: `review-comment-${comment.id}`,
      createdAt: comment.createdAt,
      id: comment.id,
      kind: 'review_comment' as const,
      activityKind: undefined,
      actor: comment.author,
      label: `${comment.path}:${comment.line}`,
      body: comment.body,
      badge: comment.outdated ? pullCopy.outdated : !comment.published ? pullCopy.pendingReview : null,
    })),
  ].sort((a, b) => (a.createdAt === b.createdAt ? a.id - b.id : a.createdAt < b.createdAt ? -1 : 1));

  /**
   * Per-line extension of the Files changed view (REQ-6-3-3). Added/deleted lines
   * get exactly one `Add comment` button (no hover prerequisite, `+` hidden), the
   * comments already anchored to that line, and — while active — the single editor
   * labelled `Comment` with `Add single comment` and `Start a review`.
   */
  const renderLineExtra = (file: DiffFile, line: DiffLine) => {
    const commentable =
      (line.type === 'added' && line.newNumber != null) || (line.type === 'deleted' && line.oldNumber != null);
    if (!commentable) return null;
    const side: 'new' | 'old' = line.type === 'added' ? 'new' : 'old';
    const lineNumber = (side === 'new' ? line.newNumber : line.oldNumber) as number;
    const key = anchorKey(file.path, side, lineNumber);
    const existing = commentsByAnchor.get(key) ?? [];
    const active =
      commentTarget != null && commentTarget.path === file.path && commentTarget.side === side && commentTarget.line === lineNumber;
    return (
      <div className="px-2 py-0.5 font-sans" data-line-anchor={`${file.path}:${side}:${lineNumber}`}>
        {existing.map((comment) => (
          <InlineCommentCard key={comment.id} comment={comment} />
        ))}
        {canReview && !active ? (
          <Button
            aria-label={moduleCopy.addComment}
            disabled={busy}
            onClick={() => {
              setReviewOpen(false);
              setCommentTarget({ path: file.path, line: lineNumber, side });
              setCommentBody('');
              setActionError(null);
            }}
          >
            <span aria-hidden="true">+</span>
          </Button>
        ) : null}
        {active ? (
          <div className="app-card p-2">
            <TextAreaField
              label={issueCopy.comment}
              value={commentBody}
              rows={3}
              onChange={(event) => setCommentBody(event.target.value)}
            />
            <div className="flex flex-wrap gap-2">
              <Button variant="primary" disabled={busy} onClick={() => submitComment(false)}>
                {moduleCopy.addSingleComment}
              </Button>
              <Button disabled={busy} onClick={() => submitComment(true)}>
                {moduleCopy.startReview}
              </Button>
              <Button
                variant="ghost"
                onClick={() => {
                  setCommentTarget(null);
                  setCommentBody('');
                }}
              >
                {authCopy.cancel}
              </Button>
            </div>
          </div>
        ) : null}
      </div>
    );
  };

  return (
    <div className="page-shell">
      <RepoHeader repository={repository} />
      <RepoNav
        owner={repository.owner}
        name={repository.name}
        active="pullRequests"
        showSettings={repository.viewerPermission.repository !== null}
      />

      <div className="mt-4">
        <h1 className="page-title">{detail.title}</h1>
        <p className="m-0 mt-1 text-sm text-muted">
          #{detail.number} · {detail.author}
        </p>
        <p className="m-0 mt-1 text-sm text-muted">
          <span data-branch-role="base">{detail.baseBranch}</span>
          <span aria-hidden="true"> ← </span>
          <span data-branch-role="compare">{detail.compareBranch}</span>
        </p>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <span className="badge" data-pr-state={detail.state}>
            {PULL_STATE_LABELS[detail.state]}
          </span>
          {detail.state === 'draft' ? (
            <>
              <Button disabled>{moduleCopy.mergePullRequest}</Button>
              {canReady ? (
                <Button variant="primary" disabled={busy} onClick={ready}>
                  {pullCopy.readyForReview}
                </Button>
              ) : null}
            </>
          ) : null}
          {detail.state === 'open' ? (
            <>
              <MergeArea
                gate={detail.merge}
                merged={null}
                canMerge={canMerge}
                busy={busy}
                onMerge={() => {
                  setCommentTarget(null);
                  setMergeOpen(true);
                }}
              />
              {canClose ? (
                <Button variant="danger" disabled={busy} onClick={() => runAction(() => pullApi.close(owner, name, detail.number))}>
                  {pullCopy.closePullRequest}
                </Button>
              ) : null}
            </>
          ) : null}
          {detail.state === 'closed' && canReopen ? (
            <Button variant="primary" disabled={busy} onClick={() => runAction(() => pullApi.reopen(owner, name, detail.number))}>
              {pullCopy.reopenPullRequest}
            </Button>
          ) : null}
        </div>
        {detail.state === 'merged' ? <MergeArea gate={detail.merge} merged={detail.merged} canMerge={false} busy={busy} onMerge={() => {}} /> : null}
        {actionError ? (
          <p className="form-error" role="alert">
            {actionError}
          </p>
        ) : null}
      </div>

      <div className="mt-3">
        <SegmentedNav
          items={[
            { label: pullCopy.conversation, to: pullPaths.detail(owner, name, detail.number), active: tab === 'conversation' },
            {
              label: contentCopy.commits,
              to: pullPaths.detail(owner, name, detail.number, 'commits'),
              active: tab === 'commits',
            },
            {
              label: contentCopy.changedFiles,
              to: pullPaths.detail(owner, name, detail.number, 'files_changed'),
              active: tab === 'files_changed',
            },
            {
              label: pullCopy.checks,
              to: pullPaths.detail(owner, name, detail.number, 'checks'),
              active: tab === 'checks',
            },
          ]}
        />
      </div>

      {tab === 'conversation' ? (
        <div className="mt-4 grid gap-6 md:grid-cols-[minmax(0,2fr)_minmax(0,1fr)]">
          <div className="min-w-0">
            <section>
              <h2 className="section-title">{pullCopy.description}</h2>
              <div className="app-card p-3 text-sm">
                {detail.body ? <p className="m-0 whitespace-pre-wrap">{detail.body}</p> : <p className="m-0 text-muted">{pullCopy.noDescription}</p>}
              </div>
            </section>

            <section className="mt-4">
              <h2 className="section-title">{pullCopy.conversation}</h2>
              <ul className="app-card m-0 list-none divide-y divide-solid divide-border p-0">
                {timeline.map((entry) => (
                  <li key={entry.key} className="px-3 py-2 text-sm" data-timeline-kind={entry.kind}>
                    <p className="m-0">
                      <span className="font-600">{entry.actor}</span>{' '}
                      {entry.label ? <span data-activity-kind={entry.activityKind}>{entry.label}</span> : null}{' '}
                      <time className="text-muted" dateTime={entry.createdAt}>
                        {formatPullTimestamp(entry.createdAt)}
                      </time>
                      {entry.badge ? <span className="badge ml-1">{entry.badge}</span> : null}
                    </p>
                    {entry.body ? <p className="m-0 mt-1 whitespace-pre-wrap">{entry.body}</p> : null}
                  </li>
                ))}
              </ul>
            </section>

            <PullChecks
              owner={owner}
              name={name}
              number={detail.number}
              check={detail.checks}
              canAdmin={isPullAdmin(role)}
              onChanged={onCheckChanged}
            />
          </div>

          <aside className="flex h-fit flex-col gap-3">
            <ReviewersPanel
              reviewers={detail.reviewers}
              candidates={candidates}
              canManage={canManageReviewers}
              busy={busy}
              onRequest={requestReviewer}
              onRemove={removeReviewer}
            />
            <ReviewsSummary reviews={detail.reviews} />
          </aside>
        </div>
      ) : null}

      {tab === 'commits' ? (
        <section className="mt-4">
          <h2 className="section-title mt-0">
            {contentCopy.commits}{' '}
            <span className="badge" aria-hidden="true">
              {diff?.commits.length ?? 0}
            </span>
          </h2>
          {diff && diff.commits.length ? (
            <ul className="app-card m-0 list-none divide-y divide-solid divide-border p-0">
              {diff.commits.map((commit) => (
                <li key={commit.id} className="flex flex-wrap items-center gap-2 px-3 py-2 text-sm">
                  <Link className="text-accent font-600" to={commit.url}>
                    {commit.shortId}
                  </Link>
                  <span>{commit.message}</span>
                  <span className="text-muted">{commit.author}</span>
                  <time className="text-muted" dateTime={commit.createdAt}>
                    {formatPullTimestamp(commit.createdAt)}
                  </time>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-muted">No commits</p>
          )}
        </section>
      ) : null}

      {tab === 'files_changed' ? (
        <section className="mt-4">
          {canReview ? (
            <Button
              disabled={busy}
              onClick={() => {
                setCommentTarget(null);
                setCommentBody('');
                setReviewOpen(true);
              }}
            >
              {moduleCopy.reviewChanges}
            </Button>
          ) : null}
          {diff ? <DiffView payload={diff} lineExtra={renderLineExtra} /> : <p className="text-muted">Loading…</p>}
        </section>
      ) : null}

      {tab === 'checks' ? (
        <PullChecks
          owner={owner}
          name={name}
          number={detail.number}
          check={detail.checks}
          canAdmin={isPullAdmin(role)}
          onChanged={onCheckChanged}
        />
      ) : null}

      <Dialog
        open={reviewOpen}
        onOpenChange={setReviewOpen}
        title={moduleCopy.reviewChanges}
        footer={
          <>
            <Button onClick={() => setReviewOpen(false)}>{authCopy.cancel}</Button>
            <Button variant="primary" disabled={busy} onClick={submitReview}>
              {moduleCopy.submitReview}
            </Button>
          </>
        }
      >
        <TextAreaField
          label={pullCopy.summary}
          value={reviewSummary}
          rows={3}
          onChange={(event) => setReviewSummary(event.target.value)}
        />
        <RadioGroup
          legend={pullCopy.reviews}
          name="review-decision"
          value={reviewDecision}
          onChange={(value) => setReviewDecision(value as 'comment' | 'approve' | 'request_changes')}
          options={[
            { value: 'comment', label: issueCopy.comment },
            { value: 'approve', label: pullCopy.approve },
            { value: 'request_changes', label: pullCopy.requestChanges },
          ]}
        />
      </Dialog>

      <Dialog
        open={mergeOpen}
        onOpenChange={setMergeOpen}
        title={moduleCopy.mergePullRequest}
        footer={
          <>
            <Button onClick={() => setMergeOpen(false)}>{authCopy.cancel}</Button>
            <Button variant="primary" disabled={busy} onClick={confirmMerge}>
              {moduleCopy.confirmMerge}
            </Button>
          </>
        }
      >
        <RadioGroup
          legend={moduleCopy.mergePullRequest}
          name="merge-method"
          value="merge_commit"
          onChange={() => {}}
          options={[{ value: 'merge_commit', label: pullCopy.createMergeCommit }]}
        />
      </Dialog>
    </div>
  );
}

export default PullDetailPage;

