function mergeTrees(ancestorTree, baseTree, compareTree) {
  const paths = new Set([...Object.keys(baseTree), ...Object.keys(compareTree)]);
  const merged = {};
  const conflicts = [];
  for (const path of paths) {
    const ancestor = ancestorTree[path];
    const base = baseTree[path];
    const compare = compareTree[path];
    const baseChanged = base !== ancestor;
    const compareChanged = compare !== ancestor;
    if (baseChanged && compareChanged && base !== compare) {
      conflicts.push(path);
      if (base !== undefined) merged[path] = base;
    } else if (compareChanged) {
      if (compare !== undefined) merged[path] = compare;
    } else if (base !== undefined) {
      merged[path] = base;
    }
  }
  return { merged, conflicts };
}

/**
 * Merge-eligibility snapshot of a PR (REQ-6-5). Computed server-side from the
 * *current* state every time it is read, and the frontend only renders it: the
 * button is visible and disabled while `eligible` is false, and `reasons[]` names
 * every unmet condition so nothing has to be discovered by clicking.
 */
export function mergeGate(db, repo, pr) {
  const baseBranch = branchRowById(db, pr.base_branch_id);
  const baseHead = baseBranch?.head_commit_id ?? null;
  const compareHead = currentCompareCommitId(db, pr);
  const rule = baseBranch ? isBranchProtected(db, pr.repo_id, baseBranch.name) : null;
  const requireApproval = Boolean(rule?.requireApproval);
  const requireCheckTest = Boolean(rule?.requireCheckTest);
  const check = getCheck(db, pr);
  const approvals = validApprovals(db, pr);
  const changesRequested = reviewState(db, pr) === 'changes_requested';
  const ancestorId = baseHead != null && compareHead != null ? mergeBase(db, baseHead, compareHead) : null;
  const { conflicts } = mergeTrees(treeOfCommit(db, ancestorId), treeOfCommit(db, baseHead), treeOfCommit(db, compareHead));
  const noChanges =
    baseHead == null || compareHead == null || ancestorsOrSelf(db, baseHead).has(compareHead);

  const reasons = [];
  if (pr.state !== 'open') reasons.push({ code: 'not_open', message: messages.PULL_NOT_OPEN });
  if (changesRequested) {
    reasons.push({ code: 'changes_requested', message: messages.PULL_MERGE_CHANGES_REQUESTED });
  }
  if (conflicts.length) reasons.push({ code: 'conflicts', message: messages.PULL_MERGE_CONFLICTS });
  if (requireApproval && approvals.length === 0) {
    reasons.push({ code: 'approval_required', message: messages.REVIEW_REQUIRED_BY_BRANCH_PROTECTION });
  }
  if (requireCheckTest && check.status !== 'success') {
    reasons.push({ code: 'check_required', message: messages.PULL_MERGE_CHECK_REQUIRED });
  }
  if (noChanges) reasons.push({ code: 'no_changes', message: messages.PULL_MERGE_NO_CHANGES });

  return {
    eligible: reasons.length === 0,
    protected: Boolean(rule),
    requireApproval,
    requireCheckTest,
    approval: { satisfied: approvals.length > 0, count: approvals.length, reviewers: approvals },
    check: { satisfied: check.status === 'success', status: check.status },
    conflicts: conflicts.length > 0,
    conflictPaths: conflicts,
    changesRequested,
    noChanges,
    reasons,
  };
}

function mergeRejection(gate) {
  const [reason] = gate.reasons;
  return validationError([fieldError(reason.code, reason.message, 'merge')]);
}

/**
 * Merge an eligible PR (REQ-6-5). Everything is reread inside one transaction:
 * the PR state, the target-branch head and compare head at merge time, the
 * protection rules, the checks and the reviews. A failure rolls back completely —
 * neither the target branch nor the PR changes. The merge commit has two parents
 * (`commits.parent_id` = target head *and* both `commit_parents` rows, §9.2) and
 * its `commit_files` are the first-parent change set, so the §7.2 consistency
 * assertion keeps holding for every commit. The compare branch is never touched,
 * and the merge does not go through the Web write path (which rightly refuses a
 * protected branch, while merging into one is the protected branch's purpose).
 */
export function mergePull(db, repo, pr, user) {
  const preflight = mergeGate(db, repo, pr);
  if (!preflight.eligible) throw mergeRejection(preflight);

  return transact(db, () => {
    const fresh = getPullById(db, pr.id);
    const gate = mergeGate(db, repo, fresh);
    if (!gate.eligible) throw mergeRejection(gate);

    const baseBranch = branchRowById(db, fresh.base_branch_id);
    const compareBranch = branchRowById(db, fresh.compare_branch_id);
    const baseHead = baseBranch.head_commit_id;
    const compareHead = currentCompareCommitId(db, fresh);
    const ancestorId = mergeBase(db, baseHead, compareHead);
    const baseTree = treeOfCommit(db, baseHead);
    const { merged } = mergeTrees(treeOfCommit(db, ancestorId), baseTree, treeOfCommit(db, compareHead));

    const commit = db
      .prepare(
        `INSERT INTO commits (repo_id, parent_id, author_id, message, tree_json)
         VALUES (?, ?, ?, ?, ?) RETURNING *`,
      )
      .get(
        repo.id,
        baseHead,
        user.id,
        `Merge pull request #${fresh.number} from ${compareBranch.name}`,
        JSON.stringify(merged),
      );
    const insertParent = db.prepare(
      'INSERT INTO commit_parents (commit_id, parent_commit_id, position) VALUES (?, ?, ?)',
    );
    insertParent.run(commit.id, baseHead, 0);
    insertParent.run(commit.id, compareHead, 1);
    const insertFile = db.prepare(
      `INSERT INTO commit_files (commit_id, path, status, additions, deletions) VALUES (?, ?, ?, ?, ?)`,
    );
    for (const file of diffTrees(baseTree, merged)) {
      insertFile.run(commit.id, file.path, file.status, file.additions, file.deletions);
    }
    db.prepare('UPDATE branches SET head_commit_id = ? WHERE id = ?').run(commit.id, baseBranch.id);
    db.prepare(
      `UPDATE pull_requests SET state = 'merged', merged_commit_id = ?, updated_at = datetime('now') WHERE id = ?`,
    ).run(commit.id, fresh.id);
    insertActivity(db, {
      kind: 'pull_request_merged',
      actorId: user.id,
      subjectType: 'pull_request',
      subjectId: fresh.id,
      payload: { number: fresh.number, mergedCommitId: commit.id, mergeCommitShortId: shortId(commit.id) },
    });
    return getPullById(db, fresh.id);
  });
}

/** Merged PRs are terminal: close/reopen/merge are all rejected (REQ-6-5/6-6). */
export function ensureNotMerged(pr) {
  if (pr.state === 'merged') {
    throw validationError([fieldError('pull_merged_terminal', messages.PULL_MERGED_TERMINAL, 'state')]);
  }
}

/**
 * The full read payload of one PR (M6a detail plus the M6b additions). The router
 * attaches `viewerPermission`, which is a permission concern.
 */
export function pullDetail(db, repo, pr, viewer) {
  return {
    pull: serializePull(db, repo, pr),
    checks: getCheck(db, pr),
    ...pullTimeline(db, pr),
    reviewComments: listReviewComments(db, pr, viewer),
    reviewers: listPullReviewers(db, pr),
    merge: mergeGate(db, repo, pr),
    merged: mergedInfo(db, pr),
  };
}

/**
 * Close an Open or Draft PR without merging (REQ-6-6). It only writes the state
 * and the timeline activity: no branch, review, comment or diff is touched.
 */
export function closePull(db, pr, user) {
  ensureNotMerged(pr);
  if (pr.state !== 'open' && pr.state !== 'draft') {
    throw validationError([fieldError('pull_not_open', messages.PULL_NOT_OPEN, 'state')]);
  }
  return transact(db, () => {
    db.prepare(`UPDATE pull_requests SET state = 'closed', updated_at = datetime('now') WHERE id = ?`).run(pr.id);
    insertActivity(db, {
      kind: 'pull_request_closed',
      actorId: user.id,
      subjectType: 'pull_request',
      subjectId: pr.id,
      payload: { number: pr.number },
    });
    return getPullById(db, pr.id);
  });
}

/** Reopen a Closed PR (REQ-6-6). Merged stays terminal. */
export function reopenPull(db, pr, user) {
  ensureNotMerged(pr);
  if (pr.state !== 'closed') {
    throw validationError([fieldError('pull_not_open', messages.PULL_NOT_OPEN, 'state')]);
  }
  return transact(db, () => {
    db.prepare(`UPDATE pull_requests SET state = 'open', updated_at = datetime('now') WHERE id = ?`).run(pr.id);
    insertActivity(db, {
      kind: 'pull_request_reopened',
      actorId: user.id,
      subjectType: 'pull_request',
      subjectId: pr.id,
      payload: { number: pr.number },
    });
    return getPullById(db, pr.id);
  });
}

/** Merger/time/result of a Merged PR, derived from the merge activity (REQ-6-5). */
export function mergedInfo(db, pr) {
  if (pr.state !== 'merged' || pr.merged_commit_id == null) return null;
  const activity = db
    .prepare(
      `SELECT a.*, u.username AS actor FROM activities a
        LEFT JOIN users u ON u.id = a.actor_id
        WHERE a.subject_type = 'pull_request' AND a.subject_id = ? AND a.kind = 'pull_request_merged'
        ORDER BY a.id DESC LIMIT 1`,
    )
    .get(pr.id);
  return {
    commitId: pr.merged_commit_id,
    shortId: shortId(pr.merged_commit_id),
    merger: activity?.actor ?? null,
    at: activity?.created_at ?? pr.updated_at,
  };
}

