    });

    const repo = repoByName(server.db, SEED_MERGE_LAB_REPO.name);
    const mainBefore = branchByName(server.db, repo.id, 'main').head_commit_id;

    const merged = await maintain.post(`${LAB_PULL(number)}/merge`);
    expect(merged.status).toBe(200);
    expect(merged.body.pull).toMatchObject({ state: 'merged' });
    expect(merged.body.pull.mergedCommitId).toBeTruthy();
    expect(merged.body.merged).toMatchObject({
      commitId: merged.body.pull.mergedCommitId,
      merger: 'pw-maintain',
    });
    expect(merged.body.activities.map((activity) => activity.kind)).toContain('pull_request_merged');

    const pull = pullByTitle(server.db, SEED_MERGE_LAB_REPO.name, SEED_MERGE_LAB_TITLES.eligible);
    const mainAfter = branchByName(server.db, repo.id, 'main').head_commit_id;
    expect(mainAfter).toBe(pull.merged_commit_id);
    expect(mainAfter).not.toBe(mainBefore);

    // The merge commit has both parents and a consistent first-parent change set.
    const parents = server.db
      .prepare('SELECT parent_commit_id, position FROM commit_parents WHERE commit_id = ? ORDER BY position')
      .all(mainAfter);
    expect(parents).toEqual([
